        assert!(auth.is_some());
        let auth = auth.unwrap();
        assert_eq!(auth.header_value, "Bearer token-value");
    }

    #[test]
    fn resolve_auth_custom_header() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "key-value".to_string());

