    #[test]
    fn creates_fetcher_with_custom_timeout() {
        let fetcher = RemoteFetcher::new(Duration::from_secs(60));
        assert_eq!(fetcher.timeout(), Duration::from_secs(60));
    }

    #[test]
    fn creates_fetcher_with_custom_cache_dir() {
