        fetcher.fetch(&url).unwrap();
        mock.assert_calls(1);

        // Corrupt the cache file by writing garbage
        let cache_path = fetcher.cache_path(&url);
        std::fs::write(&cache_path, "garbage\x00\x01\x02not yaml").unwrap();

