        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template");
        let path2 = store.content_path("http:test", "template");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_store_no_corruption() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let cache_root = temp.path().to_path_buf();

        let num_threads: usize = 8;
        let barrier = Arc::new(Barrier::new(num_threads));

        let handles: Vec<_> = (0..num_threads)
            .map(|i| {
                let root = cache_root.clone();
                let barrier = Arc::clone(&barrier);
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    // Each thread writes unique content of different size
                    let content = format!("thread-{i}-{}", "x".repeat((i + 1) * 1000));
                    barrier.wait();
                    store.store("src", "tpl", &content, 3600).unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(cache_root);
        let entry = store.load("src", "tpl").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        // Content must be a complete write from exactly one thread
        assert!(
            content.starts_with("thread-"),
            "content corrupted: unexpected prefix"
        );

        // Metadata size must match actual content length
        assert_eq!(
            entry.metadata.size_bytes,
            content.len() as u64,
            "metadata size does not match content length"
        );
    }

    #[test]
    fn store_leaves_no_temp_files() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("src", "tpl", "content", 3600).unwrap();

        for entry in fs::read_dir(temp.path()).unwrap() {
            let name = entry.unwrap().file_name().to_string_lossy().to_string();
            assert!(!name.contains(".tmp."), "temp file left behind: {name}");
        }
    }
}

