fn concurrent_save_cache_no_corruption() {
    use std::sync::{Arc, Barrier};
    use std::thread;

    let server = MockServer::start();
    let expected = "line1: value\nline2: value\n".repeat(100);

    server.mock(|when, then| {
        when.method(GET).path("/race.yml");
        then.status(200).body(&expected);
    });

    let temp = TempDir::new().unwrap();
    let cache_dir = temp.path().join("cache");
    let url = server.url("/race.yml");

    let num_threads: usize = 8;
    let barrier = Arc::new(Barrier::new(num_threads));

    let handles: Vec<_> = (0..num_threads)
        .map(|_| {
            let url = url.clone();
            let cache_dir = cache_dir.clone();
            let barrier = Arc::clone(&barrier);
            thread::spawn(move || {
                let fetcher =
                    RemoteFetcher::with_cache_dir(Duration::from_secs(10), cache_dir);
                barrier.wait();
                fetcher.fetch(&url).unwrap()
            })
        })
        .collect();

    let results: Vec<String> = handles.into_iter().map(|h| h.join().unwrap()).collect();

    for (i, result) in results.iter().enumerate() {
        assert_eq!(
            result, &expected,
            "thread {i} got corrupted content ({} bytes vs expected {})",
            result.len(),
            expected.len()
        );
    }

    // Verify cache file is intact after concurrent writes
    let fetcher =
        RemoteFetcher::with_cache_dir(Duration::from_secs(10), temp.path().join("cache"));
    let cached = fetcher.fetch(&url).unwrap();
    assert_eq!(cached, expected);
}

