use anyhow::{anyhow, Context, Result};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Duration;

/// Counter for generating unique temp file names across threads.
static TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Write content to a temporary file then atomically rename it into place.
///
/// This prevents readers from observing partially-written files when
/// multiple threads or processes write to the same cache path.
fn atomic_write(path: &Path, content: impl AsRef<[u8]>) -> Result<()> {
    let id = TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
    let file_name = path.file_name().unwrap_or_default().to_string_lossy();
    let temp_path = path.with_file_name(format!("{file_name}.tmp.{id}"));

    std::fs::write(&temp_path, content.as_ref())
        .with_context(|| format!("Failed to write cache temp file {:?}", temp_path))?;

    if let Err(e) = std::fs::rename(&temp_path, path) {
        let _ = std::fs::remove_file(&temp_path);
        return Err(e).with_context(|| format!("Failed to rename cache temp file to {:?}", path));
    }

    Ok(())
}

